// 11倍音の幾何学アニメーションスケッチ（中心から描いて、外へ→内へ繰り返し・速度1/2）
let angleOffset = 0;         // 回転角度のオフセット
let spiralProgress = 0;      // 螺旋の進行状況
let starProgress = 0;        // 星形の進行状況
let spiralForward = true;    // 螺旋が外向きかどうか
let starForward = true;      // 星形が外向きかどうか

function setup() {
  createCanvas(windowWidth, windowHeight); // 全画面に設定
	background(30);
  frameRate(60);                           // フレームレート設定
  angleMode(RADIANS);                      // 角度をラジアンモードに
}

function draw() {
  background(0,5); // 毎フレーム背景を黒で塗りつぶす

  let baseSize = max(width, height) * 0.4; // 描画サイズを短辺ベースで設定
  translate(width / 2, height / 2);        // 描画原点を画面中央に移動
  rotate(angleOffset);                     // 全体を回転

  drawSpiral(baseSize);                    // 螺旋を描画
  drawHendecagram(baseSize * 0.9);         // 星形を描画（現在は透明＝非表示）

  angleOffset += 0.005;                    // ゆっくり回転させる
}

function drawHendecagram(radius) {
  // 星形を段階的に描画（ただし現在は非表示）
  noStroke(); // 線を描かない
  noFill();   // 塗りもなし

  beginShape(); // 図形の描画開始
  for (let i = 0; i < min(starProgress, 12); i++) {
    let angle = TWO_PI * i * 3 / 11;
    let x = cos(angle) * radius;
    let y = sin(angle) * radius;
    vertex(x, y);
  }
  endShape();

  // 描画進行速度を半分に（0.025）
  if (starForward) {
    starProgress += 0.0125;
    if (starProgress >= 12) starForward = false;
  } else {
    starProgress -= 0.0125;
    if (starProgress <= 0) starForward = true;
  }
}

function drawSpiral(radius) {
  // スパイラルを段階的に描画
  noFill();                 // 塗りなし
  stroke(255, 150);         // 白の半透明線
  strokeWeight(1.5);          // 線の太さ

  beginShape();             // 図形描画開始
  for (let t = 0; t < spiralProgress; t += 0.1) {
    var angle = t * 11;
    let r = radius * t / 50;
    var x = cos(angle) * r;
    var y = sin(angle) * r;
    vertex(x, y);
  }
  endShape();

  // 描画進行速度を半分に（0.25）
  if (spiralForward) {
    spiralProgress += 0.125;
    if (spiralProgress >= 50) spiralForward = false;
  } else {
    spiralProgress -= 0.125;
    if (spiralProgress <= 0) spiralForward = true;
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight); // 画面サイズ変更に対応
}
